class ResultLog:
    def __init__(self, config, logfile, json_format=False):
        self.config = config
        self.logfile = logfile  # preferably line buffered
        self.json_format = json_format

    def write_log_entry(self, data):
        if self.json_format:
            json.dump(data, self.logfile)
            self.logfile.write('\n')
        else:
            testpath = data['testpath']
            lettercode = data['lettercode']
            longrepr = data['longrepr']
            print(f"{lettercode} {testpath}", file=self.logfile)
            for line in longrepr.splitlines():
                print(f" {line}", file=self.logfile)

    def log_outcome(self, report, code, longrepr):
        testpath = getattr(report, 'nodeid', None)
        if testpath is None:
            testpath = report.fspath
        data = {
            'testpath': testpath,
            'lettercode': code,
            'longrepr': longrepr,
            'outcome': report.outcome,
            'when': report.when,
            'duration': getattr(report, 'duration', 0),
        }
        self.write_log_entry(data)

    def pytest_runtest_logreport(self, report):
        if report.when != 'call' and report.passed:
            return
        res = self.config.hook.pytest_report_teststatus(
            report=report, config=self.config
        )
        code = res[1]
        if code == 'x':
            longrepr = str(report.longrepr)
        elif code == 'X':
            longrepr = ''
        elif report.passed:
            longrepr = ''
        elif report.failed:
            longrepr = str(report.longrepr)
        elif report.skipped:
            longrepr = str(report.longrepr[2])
        self.log_outcome(report, code, longrepr)

    def pytest_collectreport(self, report):
        if not report.passed:
            if report.failed:
                code = 'F'
                longrepr = str(report.longrepr)
            else:
                assert report.skipped
                code = 'S'
                longrepr = f"{report.longrepr[0]}:{report.longrepr[1]}: {report.longrepr[2]}"
            self.log_outcome(report, code, longrepr)

    def pytest_internalerror(self, excrepr):
        reprcrash = getattr(excrepr, 'reprcrash', None)
        path = getattr(reprcrash, 'path', None)
        if path is None:
            path = f"cwd:{py.path.local()}"
        data = {
            'testpath': path,
            'lettercode': '!',
            'longrepr': str(excrepr),
        }
        self.write_log_entry(data)

