def _print_HadamardProduct(self, expr):
    from sympy import MatAdd, MatMul, Inverse
    from sympy.printing.pretty.pretty_symbology import pretty_atom
    if self._use_unicode:
        delim = pretty_atom('Ring')
        div_delim = '⊘'  # CIRCLED DIVISION SLASH
    else:
        delim = '.*'
        div_delim = '/.'  # something to represent division

    # For simplicity, let's only support 2-arg case for division
    if len(expr.args) == 2 and isinstance(expr.args[1], Inverse):
        # We need to print the base of the Inverse
        base = expr.args[1].args[0]
        return self._print(expr.args[0]) + prettyForm(div_delim) + self._print(base)

    return self._print_seq(expr.args, None, None, delim,
            parenthesize=lambda x: isinstance(x, (MatAdd, MatMul)))

