    """Stringify a type annotation.

    :param annotation: The type annotation to stringify.
    :param add_module_names: Whether to include the module name in the result.
    :return: The stringified annotation.
    """
    if annotation is None:
        return 'None'
    if isinstance(annotation, str):
        return annotation
    if hasattr(annotation, '__name__') and not hasattr(annotation, '__origin__'):
        # This is a simple type
        if getattr(annotation, '__module__', None) == 'builtins' and \
           getattr(annotation, '__qualname__', None):
            if hasattr(annotation, '__args__'):  # PEP 585 generic
                return repr(annotation)
            else:
                return annotation.__qualname__
        elif hasattr(annotation, '__name__'):
            if add_module_names and getattr(annotation, '__module__', None):
                return '.'.join([annotation.__module__, annotation.__name__])
            else:
                return annotation.__name__
        elif hasattr(annotation, '__qualname__'):
            if add_module_names and getattr(annotation, '__module__', None):
                return '%s.%s' % (annotation.__module__, annotation.__name__)
            else:
                return annotation.__name__
    if sys.version_info >= (3, 7):  # py37+
        return _stringify_py37(annotation, add_module_names)
