def shift(self, n, freq):
    """Shift the CFTimeIndex a multiple of the given frequency.

    Parameters
    ----------
    n : int or float
        Periods to shift by
    freq : str or datetime.timedelta
        A frequency string or datetime.timedelta object to shift by

    Returns
    -------
    CFTimeIndex
    """
    from .cftime_offsets import to_offset

    if isinstance(freq, timedelta):
        return self + n * freq
    elif isinstance(freq, str):
        freq = freq.upper()  # Ensure case-insensitive matching
        if freq in ("D", "H", "T", "S", "L", "MS", "US", "NS"):
            # Handle day and smaller frequencies
            if freq == "D":
                return self + pd.Timedelta(days=n)
            elif freq == "H":
                return self + pd.Timedelta(hours=n)
            elif freq == "T":
                return self + pd.Timedelta(minutes=n)
            elif freq == "S":
                return self + pd.Timedelta(seconds=n)
            elif freq == "L":
                return self + pd.Timedelta(milliseconds=n)
            elif freq == "MS":
                return self + pd.Timedelta(milliseconds=n)
            elif freq == "US":
                return self + pd.Timedelta(microseconds=n)
            elif freq == "NS":
                return self + pd.Timedelta(nanoseconds=n)
        elif freq in ("M", "Q", "A"):
            # Handle month and larger frequencies
            if self.calendar == "360_day":
                if freq == "M":
                    return self + pd.Timedelta(days=n * 30)
                elif freq == "Q":
                    return self + pd.Timedelta(days=n * 90)
                elif freq == "A":
                    return self + pd.Timedelta(days=n * 360)
            else:
                # For other calendars, only allow integer n
                if not isinstance(n, int):
                    raise ValueError(f"Fractional shift not supported for calendar={self.calendar}")
                return self + n * to_offset(freq)
        else:
            raise ValueError(f"Unknown frequency: {freq}")
    else:
        raise TypeError(
            f"'freq' must be of type str or datetime.timedelta, got {type(freq)}")

