def _eval_is_odd(self):
    is_integer = self.is_integer
    if is_integer is False:
        return False
    if is_integer is None:
        return None

    # self is known to be an integer.
    ord2_total = 0
    known = True

    for t in self.args:
        if t.is_integer:
            if t.is_even:
                ord2_total += 1
            elif t.is_odd:
                # ord2_total += 0
                pass
            else:
                known = False
        elif t.is_Rational:
            n, d = t.as_numer_denom()
            # ord2 of n and d
            def get_ord2(x):
                if x == 0:
                    return float('inf')
                x = int(x.p)  # SymPy Integer to Python int
                if x == 0:
                    return float('inf')
                return (x & -x).bit_length() - 1
            ord2_n = get_ord2(n)
            ord2_d = get_ord2(d)
            ord2_total += ord2_n - ord2_d
        elif t.is_Pow:
            base, exp = t.as_base_exp()
            if base.is_integer and exp.is_integer:
                if exp >= 0:
                    if base.is_even:
                        ord2_total += exp
                    elif base.is_odd:
                        # ord2_total += 0
                        pass
                    else:
                        known = False
                else:
                    known = False
            else:
                known = False
        else:
            known = False

    if not known:
        return None

    # ord2 >= 1: even, ord2 == 0: odd
    return ord2_total == 0

